/* Operator workspace: map first, active exceptions second, detail on demand. */
export const escapeHTML=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeHTML;
const name=j=>(j?.name||'').replace(/^\d+ · /,'');
const total=j=>Object.values(j?.queues||{}).reduce((s,n)=>s+(Number(n)||0),0);
const phase=j=>(j?.phase||'Unreported').replaceAll('_',' ').toLowerCase().replace(/\b(ns|ew)\b/g,x=>x.toUpperCase());
export function activeIssues(project,frame,connected=true){
 const issues=[];if(!connected)issues.push({id:'c2c',severity:'warning',title:'Telemetry interrupted',detail:'Local intersection control continues. The received view is frozen.'});
 for(const j of frame.intersections){
  const p=project.intersections.find(p=>p.id===j.id),health=j.device_health||{},bad=project.devices.filter(d=>d.intersection_id===j.id&&d.role==='sensor'&&['offline','suspect'].includes(health[d.id]));
  if(j.mode==='CABINET_BACKUP')issues.push({id:j.id,severity:'error',title:`${name(p)} · cabinet backup`,detail:'Coordinator unavailable; cabinet backup is active.'});
  else if(j.mode==='FIXED_FALLBACK')issues.push({id:j.id,severity:'warning',title:`${name(p)} · fixed plan`,detail:bad.length?`${bad.length} detector${bad.length===1?' is':'s are'} not reporting normally.`:'Fixed fallback plan is active.'});
  else if(j.mode==='RECOVERING')issues.push({id:j.id,severity:'warning',title:`${name(p)} · recovering`,detail:'Waiting for the healthy recovery interval.'});
  else if(bad.length)issues.push({id:j.id,severity:'warning',title:`${name(p)} · detector health`,detail:`${bad.length} detector${bad.length===1?' needs':'s need'} attention.`});
 }
 return issues;
}
export function operationsHTML(project,{elapsed,source,controllerHTML,beaconHTML}){
 return `<div class="operations-heading"><div><span class="eyebrow">T.E.A.M. / TRAFFIC OPERATIONS</span><h1>Control center</h1><p class="study-area-label-text"><strong>Study area: A. SORIANO AVENUE</strong></p></div><div class="clock" id="clock">${elapsed}<small>${source==='sumo'?'REPLAY':'SIMULATION'} · ELAPSED</small></div></div>
 <div class="stats ops-stats" id="stats"></div>
 <div class="operations-grid operator-layout"><section class="panel operations-map-panel"><div class="panel-head"><div><span class="eyebrow">MANDAUE CITY</span><h2>Corridor overview</h2></div><div class="map-toolbar"><button class="button small" data-action="fit">Fit corridor</button><button class="button small" data-action="fullscreen">Expand map</button></div></div>
 <div class="geometry-view-bar"><div class="map-base-switch" role="group" aria-label="Map appearance"><button data-action="map-geometry" aria-pressed="true">Clean geometry</button><button data-action="map-imagery" aria-pressed="false">Satellite reference</button></div><span id="link-status" class="telemetry-status"></span></div>
 <div class="map-wrap"><div id="geo-map" class="geo-map" aria-label="A. Soriano Avenue corridor operations map"></div><div id="tile-warning" class="map-warning">Map tiles unavailable. Check the connection or change the map view.</div></div>
 <div class="ops-map-footer"><span><i class="legend-dot"></i> Detector <i class="legend-dot counter-legend"></i> Exit counter <span class="beacon-key">◇</span> Emergency beacon</span><button class="subtle-link" data-action="coverage">Lane coverage</button></div>
 <div class="control-bar"><div class="controls"><button class="button small dark" data-action="play" id="play-button">▶ Play</button><button class="button small" data-action="step">+10 s</button><button class="button small" data-action="reset">Reset</button><select aria-label="Replay speed" id="speed"><option value="1">1×</option><option value="4">4×</option><option value="10">10×</option></select></div><span class="elapsed-source">${source==='sumo'?'Recorded SUMO run':'Simulation playback'}</span></div>
 <div id="replay-scrub"></div></section>
 <aside class="operator-sidebar"><section class="panel"><div class="panel-head"><h2>Intersections</h2><span class="count-pill">${project.intersections.length}</span></div><div id="junction-list"></div><div id="selected-intersection"></div></section><section class="panel attention-panel"><div class="panel-head"><h2>Needs attention</h2><span class="count-pill" id="attention-count">0</span></div><div id="operator-attention"></div></section><section class="panel priority-panel"><div class="panel-head"><h2>Emergency priority</h2><button class="subtle-link" data-view="vehicles">Fleet ↗</button></div><div id="operator-priority"></div></section></aside></div>
 <details class="operations-diagnostics"><summary><span>Details & simulation tools</span><span>Event log, device diagnostics and test controls</span></summary><div class="diagnostics-body"><section class="panel"><div class="panel-head"><h2>Event log</h2><button class="button small" data-action="export-events">Export log</button></div><div class="event-list" id="events"></div></section><div class="split subsection"><section class="panel"><div class="panel-head"><h2>Queue trend</h2></div><div id="trend"></div></section><section class="panel"><div class="panel-head"><h2>Selected device</h2></div><div class="panel-body" id="device-detail"></div></section></div><section class="panel subsection"><div class="panel-head"><h2>Boundary passage counts</h2></div><div id="flow-balance"></div></section>${beaconHTML}${controllerHTML}<div class="panel subsection"><div class="panel-body controls"><label for="scenario">Traffic scenario</label><select id="scenario">${Object.entries({balanced:'Balanced arrivals',tidal:'Uneven demand',blocked:'Downstream blockage',resilience:'Fault, emergency & recovery'}).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></div></div><div id="beacon-map-status" hidden></div></div></details>`;
}
export function summaryHTML(project,frame,issues){const active=(frame.beacon_tracks||[]).filter(t=>t.priority_eligible).length;return [['Intersections',project.intersections.length,'in the corridor'],['Queued vehicles',frame.intersections.reduce((s,j)=>s+total(j),0),'across all approaches'],['Priority requests',active,active?'active approach':'no active requests'],['Needs attention',issues.length,issues.length?'review the action panel':'no active issues']].map(([label,value,detail])=>`<div class="stat"><span class="stat-label">${label}</span><div class="stat-value">${value}</div><span class="stat-foot">${detail}</span></div>`).join('');}
export function intersectionListHTML(project,frame,selected){return frame.intersections.map(j=>{const p=project.intersections.find(p=>p.id===j.id),mode=j.mode||'UNREPORTED',bad=['CABINET_BACKUP','FIXED_FALLBACK'].includes(mode);return `<button class="intersection-row ${j.id===selected?'active':''}" data-junction="${esc(j.id)}" aria-pressed="${j.id===selected}"><span class="intersection-status ${bad?'is-warning':mode==='RECOVERING'?'is-recovering':''}"></span><span><strong>${esc(name(p))}</strong><small>${esc(phase(j))}</small></span><span class="intersection-queue"><b>${total(j)}</b><small>queued</small></span></button>`;}).join('');}
export function selectedIntersectionHTML(project,frame,id){const j=frame.intersections.find(j=>j.id===id),p=project.intersections.find(p=>p.id===id);if(!j||!p)return '';const mode=(j.mode||'UNREPORTED').replaceAll('_',' ').toLowerCase().replace(/\b(ns|ew)\b/g,x=>x.toUpperCase());return `<div class="selected-site-detail"><div class="selected-site-title"><span>Selected intersection</span><b>${esc(p.id)}</b></div><h3>${esc(name(p))}</h3><div class="site-state"><span class="signal"><i class="r ${j.phase?.startsWith('ALL_RED')?'on':''}"></i><i class="y ${j.phase?.endsWith('YELLOW')?'on':''}"></i><i class="g ${j.phase?.endsWith('GREEN')?'on':''}"></i></span><span>${esc(phase(j))}</span><b>${esc(mode)}</b></div><div class="approach-queues">${['N','E','S','W'].map(d=>`<div><span>${d}</span><strong>${j.queues?.[d]??'—'}</strong></div>`).join('')}</div><button class="subtle-link" data-controller="${esc(p.controller_device_id)}">Device & installation details ↗</button></div>`;}
export function attentionHTML(issues){return issues.length?issues.map(i=>`<div class="operator-issue ${i.severity}" role="status"><strong>${esc(i.title)}</strong><p>${esc(i.detail)}</p></div>`).join(''):'<div class="quiet-state"><span>✓</span><div><strong>No active alerts</strong></div></div>';}
export function priorityHTML(project,frame){const tracks=(frame.beacon_tracks||[]).filter(t=>t.priority_eligible||t.status==='stale');return tracks.length?tracks.map(t=>{const vehicle=project.vehicles?.find(v=>v.beacon_id===t.beacon_id);return `<div class="active-priority"><span class="priority-symbol">◇</span><div><strong>${esc(vehicle?.call_sign||t.vehicle_id||t.beacon_id)}</strong><small>${esc(t.match?.intersection_id||'Approach pending')} · ${esc(t.status)}</small>${Number.isFinite(t.speed_mps)?`<small>${(t.speed_mps*3.6).toFixed(0)} km/h</small>`:''}</div></div>`;}).join(''):'<div class="quiet-state"><span>◇</span><div><strong>No active request</strong></div></div>';}
